def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[2] / "csrc/aten/backends/metax/generated"
    root.mkdir(parents=True, exist_ok=True)
    for name, contents in (
        ("fp32_mean.h", HEADER),
        ("fp32_mean.mc", DEVICE),
        ("fp32_host.cc", softmax_host() + "\n" + REDUCTION_AND_ACTIVATION_HOST),
    ):
        path = root / name
        result = BANNER + contents
        if args.check:
            if not path.is_file() or path.read_text() != result:
                raise SystemExit(f"stale generated MetaX FP32 source: {path}")
        else:
            path.write_text(result)


if __name__ == "__main__":
    main()
